    "にじみ" to PreviewEntry("墨の縁から不均一な広がりを加える。", "にじみの黒い円を置く。", "Adds irregular spread at the edges of the ink.", "Place a bleeding black circle.", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><defs><filter id=\"pblur\"><feGaussianBlur stdDeviation=\"3\"/></filter></defs><circle cx=\"90\" cy=\"46\" r=\"24\" fill=\"#2b2b2b\" opacity=\"0.72\" filter=\"url(#pblur)\"/><circle cx=\"90\" cy=\"46\" r=\"20\" fill=\"#2b2b2b\" opacity=\"0.62\"/></svg>"),
    "上" to PreviewEntry("画面の上側へ配置する。", "上に円を置く", "Places toward the upper side of the frame.", "Place a circle at the top", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"90\" cy=\"25\" r=\"14\" fill=\"#2b2b2b\"/><path d=\"M28 70 H152\" stroke=\"#d7d1c4\" stroke-width=\"2\"/></svg>"),
    "下" to PreviewEntry("画面の下側へ配置する。", "下に円を置く", "Places toward the lower side of the frame.", "Place a circle at the bottom", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M28 22 H152\" stroke=\"#d7d1c4\" stroke-width=\"2\"/><circle cx=\"90\" cy=\"67\" r=\"14\" fill=\"#2b2b2b\"/></svg>"),
    "中心" to PreviewEntry("画面の中心へ配置する。", "中心に円を置く", "Places at the center of the frame.", "Place a circle at center", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"90\" cy=\"46\" r=\"16\" fill=\"#2b2b2b\"/></svg>"),
    "左端" to PreviewEntry("左端近くへ寄せる。", "左端に線を置く", "Pulls close to the left edge.", "Place a line at the left edge", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M30 18 V74\" stroke=\"#2b2b2b\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M90 16 V76\" stroke=\"#d7d1c4\" stroke-width=\"2\"/></svg>"),
    "右端" to PreviewEntry("右端近くへ寄せる。", "右端に線を置く", "Pulls close to the right edge.", "Place a line at the right edge", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M90 16 V76\" stroke=\"#d7d1c4\" stroke-width=\"2\"/><path d=\"M150 18 V74\" stroke=\"#2b2b2b\" stroke-width=\"7\" stroke-linecap=\"round\"/></svg>"),
    "上端" to PreviewEntry("上の縁へ寄せる。", "上端に線を引く", "Pulls to the upper margin.", "Draw a line at the top edge", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M30 18 H150\" stroke=\"#2b2b2b\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M28 46 H152\" stroke=\"#d7d1c4\" stroke-width=\"2\"/></svg>"),
    "下端" to PreviewEntry("下の縁へ寄せる。", "下端に線を引く", "Pulls to the lower margin.", "Draw a line at the bottom edge", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M28 46 H152\" stroke=\"#d7d1c4\" stroke-width=\"2\"/><path d=\"M30 74 H150\" stroke=\"#2b2b2b\" stroke-width=\"7\" stroke-linecap=\"round\"/></svg>"),
    "始点" to PreviewEntry("線または弧の始点を選ぶ。", "前の線の始点につながる青い弧を引く", "Selects the start of a line or arc.", "Place a blue arc connected to the start of the previous line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M35 62 H145\" stroke=\"#2b2b2b\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"35\" cy=\"62\" r=\"6\" fill=\"#2b2b2b\"/></svg>"),
    "終点" to PreviewEntry("線または弧の終点を選ぶ。", "前の線の終点につながる青い弧を引く", "Selects the end of a line or arc.", "Place a blue arc connected to the end of the previous line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M35 62 H145\" stroke=\"#2b2b2b\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"145\" cy=\"62\" r=\"6\" fill=\"#2b2b2b\"/></svg>"),
    "途中" to PreviewEntry("線や弧の両端以外につなぐ。接ぐ位置は演奏で決まる。", "赤い線を置く。前の線の途中につながる小さな青い弧を置く。", "Connects along a line or arc, excluding both ends. The position is decided during performance.", "Place a red line. Place a small blue arc connected partway along the previous line.", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M30 62 H150\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\" stroke-linecap=\"round\"/><path d=\"M72 62 Q94 20 116 46\" fill=\"none\" stroke=\"#2c5fb8\" stroke-width=\"5\" stroke-linecap=\"round\"/></svg>"),
    "隅" to PreviewEntry("四隅のいずれかへ配置する。", "隅に小さな円を置く", "Places at one of the four corners.", "Place a small circle in a corner", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"36\" cy=\"25\" r=\"11\" fill=\"#2b2b2b\"/><circle cx=\"144\" cy=\"67\" r=\"11\" fill=\"#2b2b2b\" opacity=\"0.28\"/></svg>"),
    "置く" to PreviewEntry("指定した場所に一つ置く。", "中心に円を置く", "Places one element at the given location.", "Place a circle at center", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"90\" cy=\"46\" r=\"22\" fill=\"#2b2b2b\"/></svg>"),
    "並べる" to PreviewEntry("図形や組を列として並べる。", "円を横に並べる", "Lines shapes or groups up as a row.", "Line up circles", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"55\" cy=\"46\" r=\"12\" fill=\"#2b2b2b\"/><circle cx=\"90\" cy=\"46\" r=\"12\" fill=\"#2b2b2b\"/><circle cx=\"125\" cy=\"46\" r=\"12\" fill=\"#2b2b2b\"/></svg>"),
    "交互に" to PreviewEntry("二つの色や図形、組などを交互に繰り返す。組は一つとして数える。", "赤い円と青い線の組を、灰の弧と交互に5つ並べる。", "Alternates two colors, shapes, or groups. Each group counts as one.", "Line up five, alternating a group of a red circle and a blue line with a gray arc.", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"28\" cy=\"46\" r=\"8\" fill=\"#c9362d\"/><path d=\"M20 54 L36 38\" stroke=\"#2c5fb8\" stroke-width=\"3\"/><path d=\"M51 50 Q58 32 65 50\" fill=\"none\" stroke=\"#777777\" stroke-width=\"3\"/><circle cx=\"90\" cy=\"46\" r=\"8\" fill=\"#c9362d\"/><path d=\"M82 54 L98 38\" stroke=\"#2c5fb8\" stroke-width=\"3\"/><path d=\"M115 50 Q122 32 129 50\" fill=\"none\" stroke=\"#777777\" stroke-width=\"3\"/><circle cx=\"154\" cy=\"46\" r=\"8\" fill=\"#c9362d\"/><path d=\"M146 54 L162 38\" stroke=\"#2c5fb8\" stroke-width=\"3\"/></svg>"),
    "順に" to PreviewEntry("記述した色や図形、組などの順を保って繰り返す。", "赤い円・青い線・灰の弧の順に繰り返して、八つ並べる。", "Repeats colors, shapes, or groups in the written order.", "Line up eight, repeating a red circle, a blue line, and a gray arc in order.", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"27\" cy=\"46\" r=\"7\" fill=\"#c9362d\"/><path d=\"M40 53 L48 39\" stroke=\"#2c5fb8\" stroke-width=\"3\"/><path d=\"M54 50 Q61 32 68 50\" fill=\"none\" stroke=\"#777777\" stroke-width=\"3\"/><circle cx=\"78\" cy=\"46\" r=\"7\" fill=\"#c9362d\"/><path d=\"M91 53 L99 39\" stroke=\"#2c5fb8\" stroke-width=\"3\"/><path d=\"M105 50 Q112 32 119 50\" fill=\"none\" stroke=\"#777777\" stroke-width=\"3\"/><circle cx=\"129\" cy=\"46\" r=\"7\" fill=\"#c9362d\"/><path d=\"M142 53 L150 39\" stroke=\"#2c5fb8\" stroke-width=\"3\"/></svg>"),
    "埋める" to PreviewEntry("面や領域を密に満たす。", "点で埋める", "Fills a face or region densely.", "Fill with points", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"50\" cy=\"28\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"80\" cy=\"32\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"112\" cy=\"29\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"62\" cy=\"55\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"97\" cy=\"58\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"132\" cy=\"55\" r=\"5\" fill=\"#2b2b2b\"/></svg>"),
    "散らす" to PreviewEntry("要素を不規則に散布する。", "黒い点を散らす", "Scatters elements irregularly.", "Scatter black points", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"42\" cy=\"35\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"84\" cy=\"58\" r=\"4\" fill=\"#2b2b2b\"/><circle cx=\"122\" cy=\"30\" r=\"5\" fill=\"#2b2b2b\"/><circle cx=\"146\" cy=\"65\" r=\"3.5\" fill=\"#2b2b2b\"/><circle cx=\"62\" cy=\"72\" r=\"3.5\" fill=\"#2b2b2b\"/></svg>"),
    "引く" to PreviewEntry("線や弧を描く動作。", "線を引く", "The act of drawing a line or an arc.", "Draw a line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M22 56 C56 26 95 76 158 38\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\" stroke-linecap=\"round\" /></svg>"),
    "敷き詰める" to PreviewEntry("図形を規則的・反復的に配置し、明示した個数と寸法を保つ。", "四角を敷き詰める", "Places shapes regularly and repeatedly, preserving stated count and size.", "Tile squares", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><g fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"3\"><rect x=\"24\" y=\"20\" width=\"32\" height=\"30\"/><rect x=\"60\" y=\"20\" width=\"32\" height=\"30\"/><rect x=\"96\" y=\"20\" width=\"32\" height=\"30\"/><rect x=\"132\" y=\"20\" width=\"32\" height=\"30\"/><rect x=\"24\" y=\"54\" width=\"32\" height=\"30\"/><rect x=\"60\" y=\"54\" width=\"32\" height=\"30\"/><rect x=\"96\" y=\"54\" width=\"32\" height=\"30\"/><rect x=\"132\" y=\"54\" width=\"32\" height=\"30\"/></g></svg>"),
    "縦長" to PreviewEntry("縦方向に長い比率にする。", "縦長の楕円", "Makes the proportion long in the vertical direction.", "A tall ellipse", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><ellipse cx=\"90\" cy=\"46\" rx=\"20\" ry=\"34\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/></svg>"),
    "横長" to PreviewEntry("横方向に長い比率にする。", "横長の楕円", "Makes the proportion long in the horizontal direction.", "A wide ellipse", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><ellipse cx=\"90\" cy=\"46\" rx=\"42\" ry=\"18\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/></svg>"),
    "全幅" to PreviewEntry("画面幅いっぱいに広げる。", "全幅の線", "Spreads across the full width of the frame.", "A full-width line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M14 46 H166\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "半幅" to PreviewEntry("画面の半分程度の幅にする。", "半幅の線", "Sets the width to about half the frame.", "A half-width line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M45 46 H135\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M14 72 H166\" stroke=\"#d7d1c4\" stroke-width=\"2\"/></svg>"),
    "半円" to PreviewEntry("円の半分を描く。", "半円の弧を引く", "Draws half of a circle.", "Draw a semicircle arc", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M50 60 A40 40 0 0 1 130 60\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "上弦" to PreviewEntry("右に膨らむ180度の開弧として扱う。", "上弦の青い弧を引く", "Read as a 180-degree open arc bulging to the right.", "Draw a blue waxing arc", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M90 18 A28 28 0 0 1 90 74\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "下弦" to PreviewEntry("左に膨らむ180度の開弧として扱う。", "下弦の青い弧を引く", "Read as a 180-degree open arc bulging to the left.", "Draw a blue waning arc", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M90 18 A28 28 0 0 0 90 74\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "三日月" to PreviewEntry("細い月形を描く。", "三日月の弧を引く", "Draws a thin moon form.", "Draw a crescent arc", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M106 18 C76 24 62 52 82 74 C52 63 50 27 82 14 C92 12 100 14 106 18 Z\" fill=\"#2b2b2b\"/></svg>"),
    "沿う" to PreviewEntry("直前の線を参照する関係。", "前の線に沿って", "A relation that refers to the preceding line.", "along the previous line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M24 56 C58 28 104 70 156 34\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"62\" cy=\"45\" r=\"5\" fill=\"#c9362d\"/><circle cx=\"94\" cy=\"51\" r=\"5\" fill=\"#c9362d\"/><circle cx=\"126\" cy=\"43\" r=\"5\" fill=\"#c9362d\"/></svg>"),
    "触れない" to PreviewEntry("直前の形に接触しない関係。", "前の形に触れない", "A relation that makes no contact with the preceding shape.", "not touching the previous shape", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"78\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"124\" cy=\"46\" r=\"10\" fill=\"none\" stroke=\"#c9362d\" stroke-width=\"5\"/></svg>"),
    "触れる" to PreviewEntry("直前の形に接触する関係。", "前の線に触れる", "A relation that makes contact with the preceding shape.", "touching the previous line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"78\" cy=\"46\" r=\"22\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"124\" cy=\"46\" r=\"24\" fill=\"none\" stroke=\"#c9362d\" stroke-width=\"5\"/></svg>"),
    "切る" to PreviewEntry("直前の線を横切る関係。", "前の線を切る", "A relation that crosses the preceding line.", "cutting the previous line", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M38 46 H142\" stroke=\"#2b2b2b\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M92 20 L78 72\" stroke=\"#c9362d\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "間に" to PreviewEntry("直前の二つの要素の間に置く関係。", "前の二つの間に", "A relation that places between the two preceding elements.", "between the previous two", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"56\" cy=\"46\" r=\"14\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"124\" cy=\"46\" r=\"14\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"90\" cy=\"46\" r=\"8\" fill=\"#c9362d\"/></svg>"),
    "載る" to PreviewEntry("直前の形の上の縁に、下端を接して載せる関係。", "前の形に載る", "A relation that rests the shape's lower edge on the top of the preceding shape.", "resting on the previous shape", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><rect x=\"44\" y=\"52\" width=\"92\" height=\"26\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"96\" cy=\"40\" r=\"12\" fill=\"none\" stroke=\"#c9362d\" stroke-width=\"5\"/></svg>"),
    "中に" to PreviewEntry("直前の閉じた形の内側に置く関係。", "前の形の中に", "A relation that places the shape inside the preceding closed shape.", "inside the previous shape", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"90\" cy=\"46\" r=\"32\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"98\" cy=\"50\" r=\"9\" fill=\"#c9362d\"/></svg>"),
    "重なる" to PreviewEntry("直前の形に一部を重ねて置く関係。", "前の形に重なる", "A relation that overlaps part of the preceding shape.", "overlapping the previous shape", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><circle cx=\"76\" cy=\"46\" r=\"24\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><circle cx=\"108\" cy=\"46\" r=\"24\" fill=\"none\" stroke=\"#c9362d\" stroke-width=\"5\"/></svg>"),
    "横切る" to PreviewEntry("直前の形を、片方の縁から反対の縁まで越えて置く関係。", "前の形を横切る", "A relation that crosses the preceding shape from one edge past the other.", "crossing the previous shape", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><rect x=\"68\" y=\"18\" width=\"44\" height=\"56\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"5\"/><path d=\"M36 50 H144\" stroke=\"#c9362d\" stroke-width=\"6\" stroke-linecap=\"round\"/></svg>"),
    "鏡写し" to PreviewEntry("二つの形の間の軸を挟んで、位置と向きを鏡像にする。", "上に斜めの小さな赤い弧を置く。下に前の形と鏡写しの青い弧を置く。", "Mirrors the positions and orientations across the axis between two shapes.", "Place a small diagonal red arc at top. Place a blue arc at bottom, mirrored with the previous shape.", "<svg viewBox=\"0 0 180 92\" aria-hidden=\"true\"><rect width=\"180\" height=\"92\" rx=\"6\" fill=\"#fffdf8\"/><path d=\"M55 30 Q92 6 125 28\" fill=\"none\" stroke=\"#c9362d\" stroke-width=\"5\" stroke-linecap=\"round\"/><path d=\"M55 62 Q92 86 125 64\" fill=\"none\" stroke=\"#2c5fb8\" stroke-width=\"5\" stroke-linecap=\"round\"/></svg>"),
